package edu.chemistry.registry;

import edu.chemistry.EduMod;
import it.unimi.dsi.fastutil.ints.Int2ObjectMap;
import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;
import java.util.Optional;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.npc.VillagerTrades;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.trading.ItemCost;
import net.minecraft.world.item.trading.MerchantOffer;

/** The Chemist's trades, generated by gen_villager.py from the same table as the 26.x trade files. */
public final class ChemistTrades {
    private ChemistTrades() {
    }

    private static VillagerTrades.ItemListing trade(String wants, int wantsCount, String gives, int givesCount, int maxUses, int xp) {
        return (trader, random) -> new MerchantOffer(new ItemCost(item(wants), wantsCount), Optional.empty(),
            new ItemStack(item(gives), givesCount), maxUses, xp, 0.05F);
    }

    private static net.minecraft.world.item.Item item(String id) {
        return BuiltInRegistries.ITEM.get(ResourceLocation.parse(id));
    }

    /** level -> the trades a Chemist can offer at that level */
    public static Int2ObjectMap<VillagerTrades.ItemListing[]> byLevel() {
        Int2ObjectMap<VillagerTrades.ItemListing[]> map = new Int2ObjectOpenHashMap<>();
        map.put(1, new VillagerTrades.ItemListing[] {
            trade("minecraft:sand", 24, "minecraft:emerald", 1, 16, 2), // sand_emerald
            trade("minecraft:coal", 15, "minecraft:emerald", 1, 16, 2), // coal_emerald
            trade("minecraft:emerald", 1, "edu:element_1", 6, 12, 1), // emerald_hydrogen
            trade("minecraft:emerald", 1, "edu:element_8", 6, 12, 1), // emerald_oxygen
            trade("minecraft:emerald", 1, "edu:element_6", 6, 12, 1), // emerald_carbon
        });
        map.put(2, new VillagerTrades.ItemListing[] {
            trade("minecraft:glass_bottle", 8, "minecraft:emerald", 1, 12, 10), // glass_bottle_emerald
            trade("minecraft:emerald", 1, "edu:salt", 4, 12, 5), // emerald_salt
            trade("minecraft:emerald", 2, "edu:element_2", 6, 12, 5), // emerald_helium
            trade("minecraft:emerald", 2, "edu:element_11", 4, 12, 5), // emerald_sodium
            trade("minecraft:emerald", 1, "edu:colored_torch_red", 4, 12, 5), // emerald_red_torch
        });
        map.put(3, new VillagerTrades.ItemListing[] {
            trade("minecraft:quartz", 12, "minecraft:emerald", 1, 12, 20), // quartz_emerald
            trade("minecraft:emerald", 3, "edu:bleach", 1, 12, 10), // emerald_bleach
            trade("minecraft:emerald", 3, "edu:glow_stick_lime", 1, 12, 10), // emerald_lime_glow_stick
            trade("minecraft:emerald", 3, "edu:sparkler_orange", 1, 12, 10), // emerald_orange_sparkler
            trade("minecraft:emerald", 2, "edu:luminol", 2, 12, 10), // emerald_luminol
        });
        map.put(4, new VillagerTrades.ItemListing[] {
            trade("minecraft:blaze_powder", 3, "minecraft:emerald", 1, 12, 30), // blaze_powder_emerald
            trade("minecraft:emerald", 5, "edu:balloon_red", 1, 12, 15), // emerald_red_balloon
            trade("minecraft:emerald", 6, "edu:antidote", 1, 12, 15), // emerald_antidote
            trade("minecraft:emerald", 6, "edu:tonic", 1, 12, 15), // emerald_tonic
            trade("minecraft:emerald", 8, "edu:underwater_tnt", 2, 12, 15), // emerald_underwater_tnt
            trade("minecraft:emerald", 5, "edu:ice_bomb", 4, 12, 15), // emerald_ice_bomb
        });
        map.put(5, new VillagerTrades.ItemListing[] {
            trade("minecraft:emerald", 32, "edu:material_reducer", 1, 3, 30), // emerald_material_reducer
            trade("minecraft:emerald", 10, "edu:elixir", 1, 12, 30), // emerald_elixir
            trade("minecraft:emerald", 4, "edu:super_fertilizer", 4, 12, 30), // emerald_super_fertilizer
        });
        return map;
    }
}
